$$\begin{aligned}
S(q, t)\bar{S}(q, t) &= c_2^2 \psi_2 \bar{\psi}_2 + (1 - c_2^2) \psi_1 \bar{\psi}_1 \
&\quad + c_2(1 - c_2^2)^{1/2} \{\psi_2 \bar{\psi}_1 e^{-i[(E_2 - E_1)t + \beta]/\hbar} + \bar{\psi}_2 \psi_1 e^{+i[(E_2 - E_1)t + \beta]/\hbar}\}. \tag{20}
\end{aligned}$$

